// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, bool revertOnReceive) public {
        vm.assume(depositAmount > 0 && depositAmount <= type(uint128).max);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);

        address actor = address(new RevertingReceiver(revertOnReceive));
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        (bool depositOk,) = address(c).call{value: depositAmount}("");
        require(depositOk, "deposit failed");

        uint256 balanceBefore = c.balances(actor);
        bool success;
        vm.prank(actor);
        try c.withdraw() {
            success = true;
        } catch {
            success = false;
        }

        bool balancePreserved = (c.balances(actor) == balanceBefore);
        if (revertOnReceive) {
            assertTrue(!success && balancePreserved);
        } else {
            assertTrue(success && c.balances(actor) == 0);
        }
    }
}

contract RevertingReceiver {
    bool public shouldRevert;
    constructor(bool _shouldRevert) { shouldRevert = _shouldRevert; }
    receive() external payable {
        if (shouldRevert) {
            revert("revert on receive");
        }
    }
}
